import Link from "next/link";
import DeviceFrame from "./DeviceFrame";
import Reveal from "./Reveal";
import type { Project } from "@/data/site";

export function ProjectMeta({ project }: { project: Project }) {
  return (
    <div className="text-sm leading-snug">
      <p>{project.category}</p>
      <p>{project.course}</p>
      {project.note && <p>{project.note}</p>}
    </div>
  );
}

/** 首页一行作品：设备线稿在一边，文字在另一边，左右交替 */
export default function ProjectRow({ project, index }: { project: Project; index: number }) {
  const deviceLeft = project.side === "left";

  return (
    <article className="grid items-center gap-10 py-16 md:grid-cols-2 md:gap-16 md:py-24">
      <Reveal className={deviceLeft ? "" : "md:order-2"}>
        <Link
          href={`/projects/${project.slug}`}
          aria-label={project.title}
          className="mx-auto block"
          // 按原站比例：设备宽度占整行的百分比，换算成半栏里的宽度
          style={{ width: `min(100%, ${project.device.width * 2}%)` }}
        >
          <DeviceFrame
            device={project.device}
            screens={[{ src: project.cover.src, alt: project.cover.alt, box: project.device.screen }]}
            sizes="(min-width: 768px) 50vw, 100vw"
            priority={index === 0}
          />
        </Link>
      </Reveal>

      <Reveal delay={0.15} className={deviceLeft ? "" : "md:order-1"}>
        <div className="max-w-md">
          <h2 className="font-dot text-3xl sm:text-4xl">
            <Link
              href={`/projects/${project.slug}`}
              className="underline decoration-1 underline-offset-8 transition-colors hover:text-accent"
            >
              {project.title}
            </Link>
          </h2>
          <div className="mt-6">
            <ProjectMeta project={project} />
          </div>
          <p className="mt-5 text-sm leading-relaxed">{project.description}</p>
        </div>
      </Reveal>
    </article>
  );
}
